  search.focus(); setVal(search,''); await sleep(300); setVal(search,PHONE); await sleep(1000);
  const rows=[...document.querySelectorAll('#pane-side [role="row"]')];
  out.nRows=rows.length;
  out.rowTexts=rows.slice(0,3).map(r=>r.innerText.replace(/\n/g,' ~ ').slice(0,70));
  const tail=PHONE.slice(-4);
  let target=rows.find(r=>r.innerText.replace(/\D/g,'').includes(tail)) || rows[0];
  if(!target) return JSON.stringify({...out, err:'no result row'});
  out.clicked=target.innerText.replace(/\n/g,' ~ ').slice(0,60);
  target.click(); await sleep(900);
  const hdr=document.querySelector('[data-testid="conversation-info-header"]')||document.querySelector('header');
  out.chat=hdr?hdr.innerText.replace(/\n/g,' ~ ').slice(0,50):null;
  const c=document.querySelector('footer [contenteditable="true"]');
  if(!c) return JSON.stringify({...out, err:'no composer'});
  out.draftBefore=c.innerText.trim().slice(0,40);
  c.focus();
  c.dispatchEvent(new KeyboardEvent('keydown',{key:'a',code:'KeyA',ctrlKey:true,bubbles:true,cancelable:true}));
  await sleep(150);
  const dt=new DataTransfer(); dt.setData('text/plain',MSG);
  c.dispatchEvent(new ClipboardEvent('paste',{clipboardData:dt,bubbles:true,cancelable:true}));
  await sleep(500);
  out.composer=c.innerText.trim();
  out.match=out.composer===MSG;
  const btn=document.querySelector('button[aria-label="Enviar"][data-tab="11"]')||document.querySelector('button[aria-label="Enviar"]');
  out.btn=!!btn;
  if(!btn||!out.match) return JSON.stringify({...out, err:'not ready to send'});
  btn.click(); await sleep(1000);
  const c2=document.querySelector('footer [contenteditable="true"]');
  out.composerAfter=c2?c2.innerText.trim().slice(0,40):null;
  const pan=document.querySelector('[data-testid="conversation-panel-messages"]');
  out.lastMsg=pan?pan.innerText.trim().slice(-90):null;
  setVal(search,''); 
  return JSON.stringify(out);
})()
